krpano.action:
if(!hotspot[%1], exit);

calc(fy, hotspot[%1].frame * 64);
set(hotspot[%1].crop, calc:'0|' + fy + '|56|64');

inc(hotspot[%1].frame);
if(hotspot[%1].frame GE 32, set(hotspot[%1].frame, 0));

delayedcall(0.06, hs_play_loop(%1));

copy(drag_currenty, y);
copy(drag_stagey, mouse.stagey);
calc(y_min, layer[get(parent)].pixelheight - pixelheight);

if(y_min LT 0,
	asyncloop(pressed,
		calc(y, drag_currenty + (mouse.stagey - drag_stagey));
		clamp(y, get(y_min), 0);
	update_info_scrollbar(); );
);

	close_gallery();

    set(layer[info_panel].visible, true);
    set(layer[info_panel].enabled, true); set(layer[info_panel].alpha, 1.0);

    set(layer[info_panel_title].html, get:data[%1].content);
    set(layer[info_panel_text].html,  get:data[%2].content);

    set(layer[info_panel_text].y, 0);

delayedcall(0.2, 
    layer[info_panel_title].update();
    layer[info_panel_text].update();
    calc(layer[info_panel_mask].y, layer[info_panel_title].y + layer[info_panel_title].pixelheight + 30);
    calc(layer[info_panel_mask].height, -30 - get(layer[info_panel_mask].y));
    update_info_scrollbar(); );

set(layer[info_panel].alpha, 0.0);
set(layer[info_panel].visible, false);
set(layer[info_panel].enabled, false);
stoptween(layer[info_panel].alpha);

	calc(text_h, layer[info_panel_text].pixelheight);
    calc(mask_h, layer[info_panel_mask].pixelheight);

    if(text_h GT mask_h,
        set(layer[info_scroll_bar].visible, true);
        set(layer[info_scroll_track].visible, true);

        calc(layer[info_scroll_bar].height, (mask_h / text_h) * mask_h);

        calc(scroll_range, text_h - mask_h);
        calc(bar_range, mask_h - layer[info_scroll_bar].height);
        calc(layer[info_scroll_bar].y, (layer[info_panel_text].y / (scroll_range * -1)) * bar_range);
    ,
        set(layer[info_scroll_bar].visible, false);
        set(layer[info_scroll_track].visible, false);
    );

close_all_articles();


set(gallery.count,%1);

if(%1 GE 1, set(gallery.img1,%2); );
if(%1 GE 2, set(gallery.img2,%3); );
if(%1 GE 3, set(gallery.img3,%4); );
if(%1 GE 4, set(gallery.img4,%5); );
if(%1 GE 5, set(gallery.img5,%6); );
if(%1 GE 6, set(gallery.img6,%7); );
if(%1 GE 7, set(gallery.img7,%8); );
if(%1 GE 8, set(gallery.img8,%9); );
if(%1 GE 9, set(gallery.img9,%10); );
if(%1 GE 10, set(gallery.img10,%11); );
if(%1 GE 11, set(gallery.img11,%12); );
if(%1 GE 12, set(gallery.img12,%13); );
if(%1 GE 13, set(gallery.img13,%14); );
if(%1 GE 14, set(gallery.img14,%15); );
if(%1 GE 15, set(gallery.img15,%16); );

set(gallery.index,1);

set(layer[gallery_bg].visible,true);
set(layer[gallery_bg].enabled,true);

set(layer[gallery_img].onloaded, null);
set(layer[gallery_img].alpha, 0.0);
set(layer[gallery_img].url, null);


if(gallery.count LT 2,
set(layer[gallery_prev_btn].visible,false);
set(layer[gallery_next_btn].visible,false);
set(layer[gallery_prev_hit].visible,false);
set(layer[gallery_next_hit].visible,false);
,
set(layer[gallery_prev_btn].visible,true);
set(layer[gallery_next_btn].visible,true);
set(layer[gallery_prev_hit].visible,true);
set(layer[gallery_next_hit].visible,true);
);

delayedcall(0.01, gallery_show(); );

copy(drag_currenty, y);
copy(drag_stagey, mouse.stagey);
calc(y_min, layer[get(parent)].pixelheight - pixelheight);

if(y_min LT 0,
    asyncloop(pressed,
        calc(y, drag_currenty + (mouse.stagey - drag_stagey));
        clamp(y, get(y_min), 0);
    update_gallery_scrollbar(););
);

if(gallery.index == 1, set(layer[gallery_img].url, get(gallery.img1)); );
if(gallery.index == 2, set(layer[gallery_img].url, get(gallery.img2)); );
if(gallery.index == 3, set(layer[gallery_img].url, get(gallery.img3)); );
if(gallery.index == 4, set(layer[gallery_img].url, get(gallery.img4)); );
