		);

set(layer[gallery_caption].y, 0);
delayedcall(0.1, 
    layer[gallery_caption].update(); 
    update_gallery_scrollbar(); );

set(layer[gallery_bg].visible,false);
set(layer[gallery_bg].enabled,false);


set(layer[gallery_img].onloaded, null);
set(layer[gallery_img].url, null);
set(layer[gallery_img].alpha, 1.0);
set(layer[gallery_img].scale, 1.0);

set(layer[gallery_caption].html, '');

	calc(text_h, layer[gallery_caption].pixelheight);
    calc(mask_h, layer[gallery_caption_mask].pixelheight);

    if(text_h GT mask_h,
        set(layer[gallery_scroll_bar].visible, true);
        set(layer[gallery_scroll_track].visible, true);

        calc(layer[gallery_scroll_bar].height, (mask_h / text_h) * mask_h);

